function poGCLinePlayer(p,movement){
 const up=movement&&movement.current<movement.previous,move=movement?`<span class="po-gc-line-move" data-direction="${up?'up':'down'}" role="img" aria-label="Usage rank ${movement.previous} to ${movement.current} compared with the previous game"><svg viewBox="0 0 16 16" aria-hidden="true"><path d="M8 13V3m-4 4 4-4 4 4" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg><span>${movement.previous} → ${movement.current}</span></span>`:'';
 const average=n=>Number.isFinite(n)?n.toFixed(2):'—';
 return `<article class="po-gc-line-player"><div class="po-gc-line-player-top"><span class="po-gc-line-position">${esc(({L:'LW',R:'RW'})[p.position]||p.position)}${p.number?' · #'+p.number:''}</span>${move}</div><span class="po-gc-line-portrait"><svg viewBox="0 0 64 64" aria-hidden="true"><circle cx="32" cy="21" r="12"/><path d="M7 64V54c0-13 10-20 25-20s25 7 25 20v10Z"/></svg><img src="https://assets.nhle.com/mugs/nhl/latest/${p.id}.png" alt="" width="336" height="336" decoding="async" loading="lazy" data-gc-headshot></span><h5>${esc(p.name)}</h5>${p.availability?`<span class="po-gc-line-availability">${esc(p.availability)}</span>`:''}<dl><div><dt>AVG SOG</dt><dd>${average(p.stats.sog)}</dd></div>${p.position==='D'?`<div><dt>AVG BLK</dt><dd>${average(p.stats.blocks)}</dd></div>`:''}${p.position==='C'?`<div><dt>FO%</dt><dd>${Number.isFinite(p.stats.fo)?p.stats.fo.toFixed(1)+'%':'—'}</dd></div>`:''}</dl></article>`;
}
function poGCLineUnit(team,kind,rank){
 const unit=team.units[kind][rank-1],players=new Map(team.players.map(p=>[p.id,p])),label=kind==='f'?'Line '+rank:kind==='d'?'Pair '+rank:(kind==='pp'?'PP':'PK')+rank;
 if(!unit)return `<article class="po-gc-line-unit po-gc-line-unidentified"><header><h4>${label}</h4></header><p>${kind==='f'||kind==='d'?'A complete group was not identified in this game’s 5-on-5 shifts.':'A distinct '+label+' unit was not observed in this game.'}</p></article>`;
 const projected=['f','d'].includes(kind),time=`${Math.floor(unit.seconds/60)}:${String(unit.seconds%60).padStart(2,'0')}`;
 return `<article class="po-gc-line-unit" data-gc-unit="${kind}${rank}"><header><div><h4>${label}</h4><p class="po-gc-shared-toi"><b>${time}</b> together last game <span>· ${esc(unit.strength||'5-on-5')}</span></p></div>${projected?`<div class="po-gc-unit-projection"><b>${unit.expected_goals===null?'—':unit.expected_goals.toFixed(2)}</b><span>Expected goals</span></div>`:''}</header><div class="po-gc-line-players${projected?'':' po-gc-special-players'}" style="--gc-unit-size:${unit.players.length}">${unit.players.map(id=>poGCLinePlayer(players.get(id),unit.movement?.[id])).join('')}</div>${projected&&unit.expected_goals===null?'<p class="po-gc-line-note">Projection withheld because a player in this group is reported unavailable.</p>':''}</article>`;
}
function poGCSpecialRate(team,kind){
 const rate=team.special_teams[kind],rank=team.special_teams.ranks?.[kind],medal=rank<=3?['gold','silver','bronze'][rank-1]:null,label='Team '+kind.toUpperCase()+'%',value=Number.isFinite(rate)?rate.toFixed(1)+'%':'—';
 return `<div class="po-gc-special-rate${medal?' po-goalie-medal po-medal-'+medal:''}"${rank?` aria-label="${label}: ${value}, NHL rank ${rank}"`:''}><div><span>${label}</span>${rank?`<small>NHL #${rank}</small>`:''}</div><b>${value}</b></div>`;
}
function poGCLinesRender(){
 if(!poGCPreviewData)return;const data=poGCPreviewData,g=poGCGame,team=data.teams[poGCPreviewTeam],key=JSON.stringify([data.teams,data.basis,Date.parse(g.start)<Date.now(),poGCPreviewTeam]);if(key===poGCPreviewKey)return;poGCPreviewKey=key;
 const buttons=`<div class="po-gc-line-team-switch" role="group" aria-label="Team lineup">${['away','home'].map(side=>`<button type="button" data-gc-line-team="${g[side]}" aria-pressed="${poGCPreviewTeam===g[side]}"><img src="team-crests/${g[side]}.svg" alt=""><span>${esc(poGCName(g[side]))}</span></button>`).join('')}</div>`;
 const intro=`<div class="po-gc-lines-heading"><div><p class="po-gc-kicker">TEAM OUTLOOK <span>Beta</span></p><h3>Lines & matchup outlook</h3><p>Last-game combinations, ordered by shared ice time. Upcoming lineups can change.</p></div></div>${buttons}`;
 if(!team||team.status==='unavailable'){$('poGCLines').innerHTML=intro+'<div class="po-gc-panel po-gc-empty">The previous game’s shifts are not available for this team yet.</div>';return;}
 const source=team.source_game,basis=data.basis==='reconstructed'?'Reconstructed pregame projection':Date.parse(g.start)<Date.now()?'Saved pregame projection':'Upcoming-game projection',rate=value=>Number.isFinite(value)?value.toFixed(1)+'%':'—';
 const group=(kind,title,count,extra='')=>`<section class="po-gc-lines-section"><div class="po-gc-lines-section-heading"><div><h3>${title}</h3><p>${kind==='f'?'Most-used forward trios':kind==='d'?'Most-used defense pairs':'Last-game units; players can appear on more than one unit.'}</p></div>${extra}</div>${Array.from({length:count},(_,i)=>poGCLineUnit(team,kind,i+1)).join('')}</section>`;
 const others=team.other.length?`<section class="po-gc-lines-section"><div class="po-gc-lines-section-heading"><div><h3>Other dressed skaters</h3><p>Rotating players not assigned to a complete observed trio or pair.</p></div></div><div class="po-gc-line-players po-gc-line-other">${team.other.map(id=>poGCLinePlayer(team.players.find(p=>p.id===id))).join('')}</div></section>`:'';
 $('poGCLines').innerHTML=intro+`<div class="po-gc-line-context"><div><a href="${source.url}" target="_blank" rel="noopener noreferrer">Last game · ${esc(source.date)} vs ${esc(source.opponent)} ↗</a><p>${team.forward_count} forwards · ${team.defense_count} defensemen dressed. Season averages through ${esc(team.stats_through)}.</p></div><div><span>${basis}</span><b>${team.team_goals.toFixed(2)} <small>team goals</small></b></div></div><p class="po-gc-line-note">Expected goals: scoring from each group’s players, including special teams, conditional on this lineup. Arrows show changes in observed usage.</p>`+group('f','Forward lines',4)+group('d','Defense pairs',3)+others+group('pp','Power play',2,poGCSpecialRate(team,'pp'))+group('pk','Penalty kill',2,poGCSpecialRate(team,'pk'))+`<details class="po-gc-method"><summary>About these projections</summary><p>The player model allocates Sweater’s team goal forecast using only earlier games. Estimates use multi-season scoring and shooting, recent ice time, PP role and strongly regressed opponent history. Available player allocations add up to that team forecast; special-teams units overlap the regular lines and are not additional goals. A line’s number estimates goals scored by its players, and is separate from on-ice shot-quality xG.</p><p>Season per-game averages use official NHL scoring, shots and blocked shots. Faceoff percentages use total wins divided by attempts, rather than averages of game percentages. PP% and PK% use the team’s season opportunities. Units are inferred from actual shared shifts with both goalies in net; unobserved units are left unidentified. No fitted line-chemistry effect is claimed.</p><p>The allocation model was checked chronologically on 2025–26 and a current-season snapshot. That does not establish calibration of team or line totals. Skater availability, future coaching assignments and ice time remain uncertain. A historical estimate marked Reconstructed was generated later using earlier-game data, and was not a published prediction at that game’s start.</p><p><a href="${source.url}" target="_blank" rel="noopener noreferrer">NHL source game ↗</a></p></details>`;
}
function poGCEffectiveMeeting(match){
 const g={...match},current=poGCData;if(g.id===poGCGame.id&&current&&current.status!=='scheduled'){g.state=current.state;g.hg=current.home.score;g.ag=current.away.score;g.end=current.clock.type==='REG'?'REG':current.clock.type;}return g;
}
function poGCMeetingHTML(match){
 const g=poGCEffectiveMeeting(match);
 const final=['OFF','FINAL'].includes(g.state),live=['LIVE','CRIT'].includes(g.state),scored=final||live&&Number.isInteger(g.hg)&&Number.isInteger(g.ag),when=new Date(g.start).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}),status=final?'Final'+(g.end==='REG'?'':' / '+g.end):live?'LIVE':new Date(g.start).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit',timeZoneName:'short'});
 const winner=final?(g.hg>g.ag?'home':'away'):null,label=`${when}: ${poGCName(g.away)}${scored?' '+g.ag:''} at ${poGCName(g.home)}${scored?' '+g.hg:''}. ${status}.${winner?' '+poGCName(g[winner])+' won.':''} View NHL Gamecenter stats (opens in a new tab).`;
 const colours=winner?GAME_CENTER.matchupStyle(g.away,g.home,poModel.teamColors):null;
 return `<li><a class="po-gc-meeting" data-gc-meeting="${g.id}"${g.id===poGCGame.id?' data-selected="true"':''} href="https://www.nhl.com/gamecenter/${g.id}" target="_blank" rel="noopener noreferrer" aria-label="${esc(label)}"><time>${esc(when)}</time><div>${['away','home'].map(side=>`<span><img src="team-crests/${g[side]}.svg" alt=""><b>${esc(g[side])}</b>${scored?`<strong${side===winner?` class="po-gc-meeting-winner" style="--gc-meeting-winner:${colours[side]}"`:''}>${g[side==='home'?'hg':'ag']}</strong>`:''}</span>`).join('<i>@</i>')}</div><span class="po-gc-meeting-status${live?' po-live-match':''}">${esc(status)}</span>${g.type===3?'<small>Playoffs</small>':''}</a></li>`;
}
function poGCMatchupsRender(){
 if(!poGCPreviewData)return;const h=poGCPreviewData.matchups,g=poGCGame,season=String(g.id).slice(0,4),recent=h.recent.map(poGCEffectiveMeeting);
 if(poGCData?.status==='final'&&!recent.some(m=>m.id===g.id)){recent.push({id:g.id,season:Number(season)*10000+Number(season)+1,type:poGCData.game_type,date:g.date,start:g.start,home:g.home,away:g.away,state:poGCData.state,hg:poGCData.home.score,ag:poGCData.away.score,end:poGCData.clock.type});recent.sort((a,b)=>b.start.localeCompare(a.start));recent.length=Math.min(10,recent.length);}
 const host=$('poGCMatchups'),key=JSON.stringify([h.season.map(poGCEffectiveMeeting),recent]);if(host._gcKey===key)return;host._gcKey=key;
 const wins=side=>recent.filter(m=>(m.hg>m.ag?m.home:m.away)===g[side]).length;
 $('poGCMatchups').innerHTML=`<div class="po-gc-lines-heading"><div><p class="po-gc-kicker">HEAD TO HEAD</p><h3>${esc(poGCName(g.away))} & ${esc(poGCName(g.home))}</h3><p>Away @ home · Regular season and playoffs. Select a meeting for NHL Gamecenter stats. Upcoming dates and times follow your device’s time zone.</p></div></div><div class="po-gc-meeting-layout"><section class="po-gc-panel"><h3>This season</h3><p class="po-gc-subtitle">${season}–${String(Number(season)+1).slice(-2)} · ${h.season.length} scheduled meetings</p><ol class="po-gc-meetings">${h.season.length?h.season.map(poGCMeetingHTML).join(''):'<li class="po-gc-empty">No meetings are listed in the NHL season schedule yet.</li>'}</ol></section><section class="po-gc-panel"><h3>Last 10 meetings</h3><p class="po-gc-subtitle">${recent.length} completed ${recent.length===1?'meeting':'meetings'} available. The selected game is included after it finishes.</p><div class="po-gc-h2h-wins">${['away','home'].map(side=>`<span><img src="team-crests/${g[side]}.svg" alt=""><b>${esc(g[side])}</b><strong>${wins(side)}</strong><small>wins</small></span>`).join('')}</div><ol class="po-gc-meetings">${recent.length?recent.map(poGCMeetingHTML).join(''):'<li class="po-gc-empty">No completed meetings are available.</li>'}</ol></section></div><p class="po-gc-line-note">Source: <a href="https://www.nhl.com/schedule" target="_blank" rel="noopener noreferrer">NHL schedules and final scores ↗</a>. Preseason games are excluded. Each franchise keeps its own history; newer teams can have fewer than ten meetings.</p>`;
}
function poGCTab(name){
 for(const b of poGCDialog.querySelectorAll('[data-gc-tab]')){const active=b.dataset.gcTab===name;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;$(b.getAttribute('aria-controls')).hidden=!active;}
 if(name==='live'){poGCChart();if(poGCData)poGCPeriods();poGCRink();poGCQuality();poGCShootout();}$('poGCPreviewStatus').hidden=!['lines','matchups'].includes(name);if(['lines','matchups'].includes(name)){if(poGCPreviewData){poGCLinesRender();poGCMatchupsRender();}poGCPreviewLoad();}else poGCPreviewStop();
}
$('view-playoffs').addEventListener('click',e=>{const trigger=e.target.closest('[data-po-center]');if(trigger){e.preventDefault();poGCOpen(trigger.dataset.poCenter,trigger);}});
poGCDialog.addEventListener('click',e=>{
 const lineup=e.target.closest('[data-gc-line-team]');if(lineup){poGCPreviewTeam=lineup.dataset.gcLineTeam;poGCLinesRender();}if(e.target.closest('[data-gc-preview-retry]'))poGCPreviewLoad();
 const zoom=e.target.closest('[data-gc-zoom]');if(zoom)poGCZoomRink(zoom.dataset.gcZoom==='fit'?1:poGCRinkScale+(zoom.dataset.gcZoom==='in'?1:-1));
 const marker=e.target.closest('[data-gc-events]');if(marker)poGCEventShow(marker.dataset.gcEvents.split(',').map(Number));if(e.target.closest('[data-gc-events-close]')){poGCEventShow([]);}
 const tab=e.target.closest('[data-gc-tab]'),shot=e.target.closest('[data-gc-shot]');if(tab)poGCTab(tab.dataset.gcTab);if(shot)poGCSelect(Number(shot.dataset.gcShot));
 const rink=e.target.closest('#poGCRink');if(rink&&poGCData){const rect=rink.getBoundingClientRect();let best=null,distance=25;for(const s of poGCShots){if(s.x===null)continue;const dx=rect.left+(s.x+100)/200*rect.width-e.clientX,dy=rect.top+(42.5-s.y)/85*rect.height-e.clientY,d=Math.hypot(dx,dy);if(d<distance){best=s;distance=d;}}if(best)poGCSelect(best.id);}
 if(e.target===poGCDialog){const r=poGCDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)poCloseGameCenter();}
});
poGCDialog.addEventListener('change',e=>{if(['poGCTeam','poGCPeriod','poGCOutcome'].includes(e.target.id))poGCRink(true);});
poGCDialog.addEventListener('pointermove',poGCInspect,{passive:true});
poGCDialog.addEventListener('pointerdown',e=>{if(e.target.closest('#poGCChart'))poGCInspect(e);else poGCHideInspection();});
poGCDialog.addEventListener('pointerout',e=>{const chart=e.target.closest('#poGCChart');if(e.pointerType!=='touch'&&chart&&!chart.contains(e.relatedTarget))poGCHideInspection();});
poGCDialog.addEventListener('pointercancel',poGCHideInspection);
poGCDialog.addEventListener('scroll',()=>{if(poGCAnchor)poGCHideInspection();},{capture:true,passive:true});
poGCDialog.addEventListener('focusout',e=>{const chart=e.target.closest('#poGCChart');if(chart&&!chart.contains(e.relatedTarget))poGCHideInspection();});
poGCDialog.addEventListener('keydown',e=>{
 if(e.key==='Escape'&&$('poGCTooltip')&&!$('poGCTooltip').hidden){e.preventDefault();poGCHideInspection();return;}
 const marker=e.target.closest('[data-gc-events]');if(marker&&['Enter',' '].includes(e.key)){e.preventDefault();poGCEventShow(marker.dataset.gcEvents.split(',').map(Number));return;}
 const tab=e.target.closest('[data-gc-tab]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=['live','lines','matchups','availability'],index=tabs.indexOf(tab.dataset.gcTab),next=tabs[e.key==='Home'?0:e.key==='End'?3:(index+(e.key==='ArrowLeft'?-1:1)+tabs.length)%tabs.length];poGCTab(next);poGCDialog.querySelector(`[data-gc-tab="${next}"]`).focus();}
 if(e.target.id==='poGCChart'&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)&&poGCData?.forecast.points.length){e.preventDefault();const points=poGCData.forecast.points,index=poGCPoint?points.indexOf(poGCPoint):points.length-1,n=e.key==='Home'?0:e.key==='End'?points.length-1:Math.max(0,Math.min(points.length-1,index+(e.key==='ArrowLeft'?-1:1)));poGCPoint=points[n];poGCRead(poGCPoint);}
});
poGCDialog.addEventListener('error',e=>{if(e.target.matches('[data-gc-headshot]'))e.target.hidden=true;},true);
poGCDialog.addEventListener('load',e=>{if(e.target.matches('[data-gc-headshot]'))e.target.closest('.po-gc-line-portrait')?.classList.add('is-loaded');},true);
// A queued close event from the previous view must not stop a game just reopened.
poGCDialog.addEventListener('close',()=>{if(poGCDialog.open)return;poGCStop();poGCGame=null;poGCData=null;if(poGCDialog.dataset.dashboardPending){delete poGCDialog.dataset.dashboardPending;poRender();}if(!$('view-playoffs').hidden){const trigger=poGCReturn?.isConnected?poGCReturn:[...document.querySelectorAll(`[data-po-center="${poGCReturnID}"]`)].find(e=>e.getClientRects().length);trigger?.focus({preventScroll:true});}});
$('poGCClose').onclick=()=>poCloseGameCenter();
function poGCResume(){if(!poGCDialog.open||document.hidden)return;poGCLoad();if(poGCPreviewVisible())poGCPreviewLoad();}
document.addEventListener('visibilitychange',()=>{if(!poGCDialog.open)return;if(document.hidden)poGCStop();else poGCResume();});
window.addEventListener('online',poGCResume);window.addEventListener('focus',poGCResume);window.addEventListener('pageshow',poGCResume);
let poGCWidth=0;new ResizeObserver(entries=>{const width=entries[0]?.contentRect.width;if(width&&width!==poGCWidth){poGCWidth=width;if(poGCDialog.open&&poGCGame&&!$('poGCLive').hidden)poGCChart();}}).observe(poGCDialog);
